const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const http = require('http');
const https = require('https');
const { URL, URLSearchParams } = require('url');
const { Buffer } = require('buffer');

function slugify(value) {
  return String(value ?? '').trim().toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 80) || 'stackgeist-asset';
}
function normalizeSize(input = {}) {
  const presets = { hero: [1344, 768], wide: [1344, 768], square: [1024, 1024], pin: [832, 1216], pinterest: [832, 1216], card: [1024, 768], thumb: [1024, 576], thumbnail: [1024, 576] };
  const [width, height] = presets[input.size || input.aspect || 'hero'] || presets.hero;
  return { width, height };
}

function httpRequest(url, options = {}) {
  return new Promise((resolve, reject) => {
    const parsed = new URL(url);
    const body = options.body ? Buffer.from(options.body) : null;
    const lib = parsed.protocol === 'https:' ? https : http;
    const req = lib.request(parsed, {
      method: options.method || 'GET',
      headers: { ...(options.headers || {}), ...(body ? { 'Content-Length': body.length } : {}) },
    }, (res) => {
      const chunks = [];
      res.on('data', (chunk) => chunks.push(chunk));
      res.on('end', () => resolve({ status: res.statusCode, ok: res.statusCode >= 200 && res.statusCode < 300, body: Buffer.concat(chunks) }));
    });
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}
async function fetchJson(url, options = {}) {
  const res = await httpRequest(url, options);
  const text = res.body.toString('utf8');
  if (!res.ok) throw new Error(`${options.method || 'GET'} ${url} failed ${res.status}: ${text.slice(0, 500)}`);
  return text ? JSON.parse(text) : {};
}
async function waitForHistory(host, promptId) {
  const started = Date.now();
  while (Date.now() - started < 180000) {
    const history = await fetchJson(`${host}/history/${promptId}`);
    if (history[promptId]) return history[promptId];
    await new Promise((resolve) => setTimeout(resolve, 1500));
  }
  throw new Error(`Timed out waiting for ${promptId}`);
}
const input = $json.body || $json;
const host = 'http://172.28.96.1:8189';
const repoRoot = '/workspace/stackgeist-site';
const slug = slugify(input.slug || input.title);
const type = slugify(input.type || 'hero');
const { width, height } = normalizeSize(input);
const info = await fetchJson(`${host}/object_info/CheckpointLoaderSimple`);
const checkpoints = info.CheckpointLoaderSimple.input.required.ckpt_name[0];
const checkpoint = checkpoints.includes(input.checkpoint) ? input.checkpoint : (checkpoints.includes('Juggernaut-XL_v9_RunDiffusionPhoto_v2.safetensors') ? 'Juggernaut-XL_v9_RunDiffusionPhoto_v2.safetensors' : checkpoints[0]);
if (!checkpoint) throw new Error('No ComfyUI checkpoints available');
const seed = input.seed === -1 || input.seed == null ? crypto.randomInt(1, 2 ** 32 - 1) : Number(input.seed);
const positive = input.positive || [`StackGeist ${type} artwork`, input.title || '', input.prompt || '', 'dark terminal/operator aesthetic', 'black graphite background, subtle phosphor green and amber glow, cyber workstation mood', 'premium editorial tech illustration, sharp composition, cinematic lighting', 'no readable text, no logos, no product packaging, no fake screenshots'].filter(Boolean).join(', ');
const workflow = {
  '3': { class_type: 'KSampler', inputs: { seed, steps: Number(input.steps || 18), cfg: Number(input.cfg || 6), sampler_name: 'euler', scheduler: 'normal', denoise: 1, model: ['4', 0], positive: ['6', 0], negative: ['7', 0], latent_image: ['5', 0] } },
  '4': { class_type: 'CheckpointLoaderSimple', inputs: { ckpt_name: checkpoint } },
  '5': { class_type: 'EmptyLatentImage', inputs: { width, height, batch_size: Number(input.count || 1) } },
  '6': { class_type: 'CLIPTextEncode', inputs: { text: positive, clip: ['4', 1] } },
  '7': { class_type: 'CLIPTextEncode', inputs: { text: input.negative || 'readable text, watermark, logo, brand name, fake product packaging, blurry, low quality', clip: ['4', 1] } },
  '8': { class_type: 'VAEDecode', inputs: { samples: ['3', 0], vae: ['4', 2] } },
  '9': { class_type: 'SaveImage', inputs: { filename_prefix: `StackGeist/${slug}/${type}`, images: ['8', 0] } },
};
const queued = await fetchJson(`${host}/prompt`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ prompt: workflow, client_id: `n8n-stackgeist-${Date.now()}` }) });
const promptId = queued.prompt_id;
const history = await waitForHistory(host, promptId);
const images = Object.values(history.outputs || {}).flatMap((node) => node.images || []);
if (!images.length) throw new Error(`ComfyUI prompt ${promptId} produced no images`);
const outputRoot = path.join(repoRoot, 'public', 'generated', 'stackgeist', slug);
fs.mkdirSync(outputRoot, { recursive: true });
const outputs = [];
for (let i = 0; i < images.length; i++) {
  const img = images[i];
  const params = new URLSearchParams({ filename: img.filename, subfolder: img.subfolder || '', type: img.type || 'output' });
  const res = await httpRequest(`${host}/view?${params}`);
  if (!res.ok) throw new Error(`GET /view failed ${res.status}`);
  const bytes = res.body;
  const ext = path.extname(img.filename) || '.png';
  const dest = path.join(outputRoot, `${type}-${promptId.slice(0, 8)}-${i + 1}${ext}`);
  fs.writeFileSync(dest, bytes);
  outputs.push({ file: path.relative(repoRoot, dest).replace(/\\/g, '/'), bytes: bytes.length, comfy: img });
}
const manifest = { generatedAt: new Date().toISOString(), slug, type, title: input.title || '', prompt: positive, checkpoint, seed, width, height, promptId, outputs };
fs.writeFileSync(path.join(outputRoot, 'manifest.json'), JSON.stringify(manifest, null, 2) + '\n');
return [{ json: manifest }];
